/* Foot Run - stride by stride feedback from a Puck.js v2 on a shoe.

 The Puck runs accel_fifo.js (foot-mounted inertial navigation: it counts
 strides and measures each one's displacement), which this app sends it:

 1. Connect to the nearest Puck.js. If it already has the stride service
    (0xBCDE), it's running the code - skip to 4
 2. Over its Nordic UART (its console): reset(), then make sure its Storage
    has footrun.js (the code) and footrun.bin (the compiled C), writing them
    if their CRC32s differ, and run eval(require("Storage").read("footrun.js")).
    Code run from Storage keeps its functions in flash, which is what lets it
    fit in the Puck's RAM
 3. The stride service only appears once the Puck's Bluetooth restarts, so
    disconnect, and connect to the same Puck again
 4. Subscribe to the stride characteristic (0xABCE): 5 little-endian float32s,
    stride count, dx, dy, dz (m), duration (s; 0 = first after standing).
    It's notified on every stride, and repeated every second when nothing's
    happening (the same count - a heartbeat). Each new stride buzzes and is
    shown; heartbeats just show the Puck's still there

 One stride is that foot's movement from landing to landing, ie. two steps.
 PUCK_JS/PUCK_BIN below are made from ../accel_fifo.js by build.py.
*/

// BEGIN PUCK_CODE (generated by build.py - don't edit)
var PUCK_JS = "var POLL_MS=250;var CHUNK_SAMPLES=20;var BETA=.3;var ACC_TH=.3;var GYRO_TH=1.5;var MAG_HZ=20;var NORTHERN_HEMISPHERE=true;var MAG_CAL_FILE='puckmag.json';var FIFO_CTRL1=6,FIFO_CTRL2=7,FIFO_CTRL3=8,FIFO_CTRL4=9,FIFO_CTRL5=10,INT1_CTRL=13,CTRL1_XL=16,CTRL2_G=17,CTRL6_C=21,CTRL7_G=22,FIFO_STATUS1=58,FIFO_DATA_OUT_L=62;var FIFO_CTRL5_ON=5<<3|6;var WORDS_PER_SAMPLE=6,BYTES_PER_SAMPLE=12;var c=function(){var bin=require('Storage').read('footrun.bin');return{reset:E.nativeCall(109,'void(int)',bin),process:E.nativeCall(181,'void(int, int, int)',bin),fitEllipsoid:E.nativeCall(3417,'int(int, int, int)',bin)};}();var S_BETA=4,S_MAG=5,S_USEMAG=8,S_ACC=9,S_ACC_TH=12,S_GYRO_TH=13,S_BIAS=22,S_STRIDES=25,S_STRIDE=26,S_STRIDE_TIME=29,S_TOTAL=31,S_DISTANCE=34,S_SATURATED=35,S_STANCE=36;var state=new Float32Array(37);var stateAddr=E.getAddressOf(state,true);var sampleBuf=new Uint8Array(CHUNK_SAMPLES*BYTES_PER_SAMPLE);var sampleAddr=E.getAddressOf(sampleBuf,true);if(!stateAddr||!sampleAddr)throw new Error(\"Couldn't get flat buffers for compiled code\");var count=0;var overruns=0;function onSample(d,n){sampleBuf.set(d);c.process(sampleAddr,n,stateAddr);count+=n;}function getHeading(){var q0=state[0],q1=state[1],q2=state[2],q3=state[3];return Math.atan2(2*(q0*q3+q1*q2),1-2*(q2*q2+q3*q3))*180/Math.PI;}function poll(){var st=Puck.accelRd(FIFO_STATUS1,4);if(st[1]&16)return;if(st[1]&64){overruns++;Puck.accelWr(FIFO_CTRL5,0);Puck.accelWr(FIFO_CTRL5,FIFO_CTRL5_ON);return;}var words=st[0]|(st[1]&7)<<8;var pattern=st[2]|(st[3]&3)<<8;if(pattern){var skip=WORDS_PER_SAMPLE-pattern;if(words<skip)return;Puck.accelRd(FIFO_DATA_OUT_L,skip*2);words-=skip;}var samples=words/WORDS_PER_SAMPLE|0;while(samples>0){var n=Math.min(samples,CHUNK_SAMPLES);var d;try{d=Puck.accelRd(FIFO_DATA_OUT_L,n*BYTES_PER_SAMPLE);}catch(e){}if(d===undefined){if(CHUNK_SAMPLES==1)return;CHUNK_SAMPLES=CHUNK_SAMPLES>>1;continue;}onSample(d,n);samples-=n;}}var magCal;var magCalPrev;var magCalData;function loadMagCal(){var cal=require('Storage').readJSON(MAG_CAL_FILE,true);if(!cal||!cal.offset||!cal.matrix||cal.offset.length!=3||cal.matrix.length!=9||cal.offset.concat(cal.matrix).some(function(v){return typeof v!='number'||!isFinite(v);}))return undefined;return cal;}function clearMagCal(){require('Storage').erase(MAG_CAL_FILE);magCal=undefined;state[S_USEMAG]=0;print('Magnetometer calibration deleted');}var MAG_CAL_SAMPLES=300;function onMag(m){poll();if(magCalData)addMagCalSample(m);if(!magCal)return;var o=magCal.offset,T=magCal.matrix;var x=m.x-o[0],y=m.y-o[1],z=m.z-o[2];state[S_MAG]=T[0]*x+T[1]*y+T[2]*z;state[S_MAG+1]=T[3]*x+T[4]*y+T[5]*z;state[S_MAG+2]=T[6]*x+T[7]*y+T[8]*z;state[S_USEMAG]=1;}function calibrateMag(seconds){if(magCalData)return print('Already calibrating');seconds=seconds||15;magCalPrev=magCal;magCal=undefined;state[S_USEMAG]=0;magCalData={n:0,still:0,m:new Int16Array(MAG_CAL_SAMPLES*3),d:new Int8Array(MAG_CAL_SAMPLES*3)};print('Magnetometer calibration: slowly turn Puck.js in every direction for '+seconds+'s');setTimeout(finishMagCal,seconds*1e3);}function addMagCalSample(m){var cal=magCalData;if(cal.n>=MAG_CAL_SAMPLES)return;var i=cal.n*3;cal.m.set([m.x,m.y,m.z],i);cal.n++;var ax=state[S_ACC],ay=state[S_ACC+1],az=state[S_ACC+2];var a=Math.sqrt(ax*ax+ay*ay+az*az);if(a<.9||a>1.1)return;cal.d[i]=-127*ax/a;cal.d[i+1]=-127*ay/a;cal.d[i+2]=-127*az/a;cal.still++;}function finishMagCal(){var cal=magCalData,i,j,k;magCalData=undefined;function fail(why){magCal=magCalPrev;print('Magnetometer calibration failed - '+why+(magCal?'. Keeping the previous calibration':''));}if(cal.n<100||cal.still<50)return fail('turn Puck.js through more directions ('+cal.n+' samples, '+cal.still+' still)');var fit=new Float32Array(15);var magAddr=E.getAddressOf(cal.m,true),fitAddr=E.getAddressOf(fit,true);if(!magAddr||!fitAddr)return fail(\"couldn't get flat buffers for compiled code\");if(!c.fitEllipsoid(magAddr,cal.n,fitAddr))return fail(\"couldn't fit an ellipsoid - turn Puck.js through more directions\");var off=[fit[0],fit[1],fit[2]],W=new Float32Array(fit.buffer,12,9),radiiRaw=new Float32Array(fit.buffer,48,3);var C=new Float64Array(9),err=0;for(i=0;i<cal.n*3;i+=3){if(i%60==0)poll();var x=cal.m[i]-off[0],y=cal.m[i+1]-off[1],z=cal.m[i+2]-off[2];var u=[W[0]*x+W[1]*y+W[2]*z,W[3]*x+W[4]*y+W[5]*z,W[6]*x+W[7]*y+W[8]*z];var len=Math.sqrt(u[0]*u[0]+u[1]*u[1]+u[2]*u[2]);err+=(len-1)*(len-1);if(!cal.d[i]&&!cal.d[i+1]&&!cal.d[i+2])continue;for(j=0;j<3;j++)for(k=0;k<3;k++)C[j*3+k]+=cal.d[i+j]*u[k]/len;}var perms=[[0,1,2],[1,2,0],[2,0,1],[0,2,1],[1,0,2],[2,1,0]];var best,bestIdx,bestScore=-1;perms.forEach(function(p,idx){var score=Math.abs(C[p[0]])+Math.abs(C[3+p[1]])+Math.abs(C[6+p[2]]);if(score>bestScore){bestScore=score;best=p;bestIdx=idx;}});var hemi=NORTHERN_HEMISPHERE?1:-1;var sign=best.map(function(k,j){return C[j*3+k]*hemi<0?-1:1;});var T=[];for(j=0;j<3;j++)for(k=0;k<3;k++)T[j*3+k]=sign[j]*W[best[j]*3+k];magCal={offset:off,matrix:T};try{require('Storage').writeJSON(MAG_CAL_FILE,magCal);}catch(e){print(\"Warning: couldn't save \"+MAG_CAL_FILE+' ('+e+') - calibration will be lost on restart');}var dip=Math.asin(E.clip(bestScore/(127*cal.still),-1,1))*180/Math.PI;var radii=[radiiRaw[0].toFixed(0),radiiRaw[1].toFixed(0),radiiRaw[2].toFixed(0)];print('Magnetometer calibrated from '+cal.n+' samples ('+cal.still+' still)');print(' centre '+off.map(function(v){return v.toFixed(0);}).join(',')+', ellipsoid radii '+radii.join(',')+', RMS distance from unit sphere '+(100*Math.sqrt(err/cal.n)).toFixed(1)+'%');print(' IMU x,y,z = mag '+best.map(function(k,j){return(sign[j]<0?'-':'+')+'xyz'[k];}).join(',')+', dip '+dip.toFixed(1)+' deg');var det=(bestIdx<3?1:-1)*sign[0]*sign[1]*sign[2];if(det<0)print('Warning: axis mapping is a reflection - calibration is probably poor, try again');}function start(){Puck.accelOn(208);if(!(Puck.accelRd(15,1)instanceof Uint8Array)){Puck.accelOff();throw new Error('Firmware '+process.env.VERSION+' too old - Puck.accelRd(reg,cnt) needs 2v29+');}Puck.accelWr(INT1_CTRL,0);Puck.accelWr(CTRL1_XL,84);Puck.accelWr(CTRL2_G,92);Puck.accelWr(CTRL6_C,0);Puck.accelWr(CTRL7_G,0);Puck.accelWr(FIFO_CTRL5,0);Puck.accelWr(FIFO_CTRL1,0);Puck.accelWr(FIFO_CTRL2,0);Puck.accelWr(FIFO_CTRL3,9);Puck.accelWr(FIFO_CTRL4,0);c.reset(stateAddr);state[S_BETA]=BETA;state[S_ACC_TH]=ACC_TH;state[S_GYRO_TH]=GYRO_TH;Puck.accelWr(FIFO_CTRL5,FIFO_CTRL5_ON);setInterval(poll,POLL_MS);Puck.on('mag',onMag);Puck.magOn(MAG_HZ);magCal=loadMagCal();if(magCal)print('Using magnetometer calibration from '+MAG_CAL_FILE);else print('Magnetometer not calibrated - run calibrateMag() and turn Puck.js in every direction');}var STRIDE_SERVICE='BCDE';var STRIDE_CHAR='ABCE';var CHECK_MS=100;var HEARTBEAT_MS=1e3;var strideBytes=new Uint8Array(state.buffer,S_STRIDES*4,20);var lastStrides=0,lastSent=0;function setupBluetooth(){var s={};s[STRIDE_SERVICE]={};s[STRIDE_SERVICE][STRIDE_CHAR]={value:strideBytes,maxLen:20,readable:true,notify:true,description:'Stride n,dx,dy,dz,dt (float32)'};NRF.setServices(s,{advertise:[STRIDE_SERVICE],uart:true});}function checkStride(){var now=Date.now();var isNew=state[S_STRIDES]!=lastStrides;if(!isNew&&now-lastSent<HEARTBEAT_MS)return;lastStrides=state[S_STRIDES];lastSent=now;var u={};u[STRIDE_SERVICE]={};u[STRIDE_SERVICE][STRIDE_CHAR]={value:strideBytes,notify:true};try{NRF.updateServices(u);}catch(e){}}function status(){var dx=state[S_STRIDE],dy=state[S_STRIDE+1],dt=state[S_STRIDE_TIME];print(count+' samples, '+overruns+' FIFO overruns, '+state[S_SATURATED]+' clipped samples (+/-16g or 2000 deg/s)');print('Heading '+getHeading().toFixed(1)+(state[S_USEMAG]?' (magnetic)':' (relative)')+', foot '+(state[S_STANCE]?'down':'moving'));print(state[S_STRIDES]+' strides, '+state[S_DISTANCE].toFixed(1)+'m. Last '+Math.sqrt(dx*dx+dy*dy).toFixed(2)+'m'+(dt?' in '+dt.toFixed(2)+'s ('+(120/dt).toFixed(0)+' steps/min)':''));}start();setupBluetooth();setInterval(checkStride,CHECK_MS);";
var PUCK_JS_CRC = 1701810762;
var PUCK_BIN = ""; // base64
var PUCK_BIN_CRC = 1083497240;
// END PUCK_CODE

var NUS = "6e400001-b5a3-f393-e0a9-e50e24dcca9e";
var NUS_TX = "6e400003-b5a3-f393-e0a9-e50e24dcca9e"; // notifications from the Puck's console
var NUS_RX = "6e400002-b5a3-f393-e0a9-e50e24dcca9e"; // writes to the Puck's console
var STRIDE_SERVICE = "bcde", STRIDE_CHAR = "abce";
var BUZZ_MS = 60;
var QUIET_MS = 3000; // heartbeats come every second - this long without one is a problem

var session;  // the current connection: { device, gatt, rx, phase, ... }
var run = {   // what's been seen
  last: undefined,   // the Puck's stride count from the last notification
  strides: 0,        // strides counted while connected
  length: 0,         // last stride's horizontal length (m)
  cadence: 0,        // steps per minute from the last stride's duration
  distance: 0,       // total horizontal distance (m)
  heard: 0           // Date.now() of the last notification
};

function show(lines) {
  var r = Bangle.appRect;
  g.reset().clearRect(r).setFont("6x8", 2).setFontAlign(0, 0);
  var wrapped = [];
  lines.forEach(function(l) { wrapped = wrapped.concat(l ? g.wrapString(l, r.w - 4) : [""]); });
  var y = r.y + (r.h - wrapped.length * 20) / 2 + 10;
  wrapped.forEach(function(l) { g.drawString(l, r.x + r.w / 2, y); y += 20; });
}

// ---------------------------------------------------------------- Running

function draw() {
  var r = Bangle.appRect, x = r.x + r.w / 2, quiet = Date.now() - run.heard;
  g.reset().clearRect(r).setFontAlign(0, 0);
  g.setFont("Vector", 44).drawString(run.strides, x, r.y + 30);
  g.setFont("6x8", 1).drawString("strides", x, r.y + 56);
  g.setFont("6x8", 2);
  g.drawString(run.length ? run.length.toFixed(2) + " m" : "-", x, r.y + 78);
  g.drawString(run.cadence ? run.cadence.toFixed(0) + " steps/min" : "-", x, r.y + 100);
  g.drawString(run.distance.toFixed(0) + " m total", x, r.y + 122);
  g.setFont("6x8", 1);
  g.drawString(quiet > QUIET_MS ? "no data for " + Math.round(quiet / 1000) + "s" : "connected - BTN: menu", x, r.y2 - 8);
}

// The stride characteristic's value when (re)connecting: the Puck's count
// now. Strides it counted while we weren't connected are added (silently -
// their lengths aren't known)
function syncStrides(d) {
  var n = d.getFloat32(0, true);
  run.heard = Date.now();
  if (run.last === undefined || n < run.last) run.last = n; // first time, or the Puck restarted
  else if (n > run.last) { run.strides += n - run.last; run.last = n; }
}

// A notification from the stride characteristic
function onStride(event) {
  var d = event.target.value;
  var n = d.getFloat32(0, true), dx = d.getFloat32(4, true), dy = d.getFloat32(8, true);
  var dt = d.getFloat32(16, true);
  run.heard = Date.now();
  if (run.last === undefined || n < run.last) {
    // Before the first read, or the Puck restarted: start counting from here
    run.last = n;
  } else if (n > run.last) {
    // New stride(s) - normally one; more if notifications were missed
    run.strides += n - run.last;
    run.last = n;
    run.length = Math.sqrt(dx * dx + dy * dy);
    run.cadence = dt > 0 ? 120 / dt : 0; // a stride is two steps
    run.distance += run.length;
    Bangle.buzz(BUZZ_MS);
  }
  // n == run.last: a heartbeat - nothing new
  if (session && session.phase == "running" && !session.menu) draw();
}

// ---------------------------------------------------------------- Connecting

/* Connect to the Puck, uploading the code first if it's not running it, and
 subscribe to its strides. */
function connect() {
  var s = session = { phase: "connect", done: false, line: "", lines: [] };
  Bangle.setUI({ mode: "custom", btn: function() { stop("Cancelled"); } });
  show(["Scanning for", "Puck.js...", "", "BTN: cancel"]);
  function check(x) { if (s.done) throw "Cancelled"; return x; }
  NRF.requestDevice({ filters: [{ namePrefix: "Puck.js" }], timeout: 20000 }).then(check).then(function(device) {
    s.device = device;
    device.on("gattserverdisconnected", function() { onDisconnect(s); });
    show(["Connecting to", device.name || "Puck.js", "", "BTN: cancel"]);
    return device.gatt.connect();
  }).then(check).then(function(gatt) {
    s.gatt = gatt;
    // Already running the code? Then it has the stride service
    return gatt.getPrimaryService(STRIDE_SERVICE).then(function() { return true; }, function() { return false; });
  }).then(check).then(function(running) {
    if (running) return;
    return upload(s).then(check).then(function() {
      // The stride service only appears once the Puck's Bluetooth restarts
      show(["Restarting", "Puck Bluetooth", "", "BTN: cancel"]);
      s.reconnecting = true;
      s.gatt.disconnect();
      return new Promise(function(resolve) { setTimeout(resolve, 2500); });
    }).then(check).then(function() {
      return s.device.gatt.connect();
    }).then(check).then(function(gatt) {
      s.gatt = gatt;
      s.reconnecting = false;
    });
  }).then(function() {
    return s.gatt.getPrimaryService(STRIDE_SERVICE);
  }).then(check).then(function(service) {
    return service.getCharacteristic(STRIDE_CHAR);
  }).then(check).then(function(c) {
    c.on("characteristicvaluechanged", onStride);
    return c.startNotifications().then(function() { return c.readValue(); }).then(syncStrides);
  }).then(check).then(function() {
    return s.gatt.getPrimaryService(NUS).then(function(nus) { return nus.getCharacteristic(NUS_RX); })
      .then(function(rx) { s.rx = rx; }, function() {}); // for "Stop Puck" - not essential
  }).then(check).then(function() {
    s.phase = "running";
    Bangle.setUI({ mode: "custom", btn: showRunMenu });
    s.timer = setInterval(function() { if (!s.menu) draw(); }, 1000);
    draw();
  }).catch(function(e) {
    if (session == s && !s.done) stop("Error: " + e);
  });
}

/* Put footrun.js and footrun.bin in the Puck's Storage (if they're not
 already there) and run the code. */
function upload(s) {
  var nus, tx;
  show(["Uploading", "code to Puck", "", "BTN: cancel"]);
  return s.gatt.getPrimaryService(NUS).then(function(service) {
    nus = service;
    return nus.getCharacteristic(NUS_TX);
  }).then(function(c) {
    tx = c;
    tx.on("characteristicvaluechanged", function(e) { onText(s, e.target.value); });
    return tx.startNotifications();
  }).then(function() {
    return nus.getCharacteristic(NUS_RX);
  }).then(function(rx) {
    s.rx = rx;
    // Stop whatever the Puck is running (\x10 = don't echo the line back)
    return send(s, "\x10reset();\n");
  }).then(function() {
    return new Promise(function(resolve) { setTimeout(resolve, 1500); });
  }).then(function() {
    return ask(s, "E.CRC32(require('Storage').read('footrun.js')||'')+' '+E.CRC32(require('Storage').read('footrun.bin')||'')");
  }).then(function(reply) {
    var crcs = reply.split(" "), cmds = [], i, len;
    if (+crcs[1] != PUCK_BIN_CRC) {
      // In chunks of 384 bytes = 512 base64 characters
      len = atob(PUCK_BIN).length;
      for (i = 0; i < PUCK_BIN.length; i += 512)
        cmds.push("require('Storage').write('footrun.bin',atob('" + PUCK_BIN.substr(i, 512) + "')," +
                  (i / 4 * 3) + (i ? "" : "," + len) + ");");
    }
    if (+crcs[0] != PUCK_JS_CRC) {
      for (i = 0; i < PUCK_JS.length; i += 384)
        cmds.push("require('Storage').write('footrun.js'," + JSON.stringify(PUCK_JS.substr(i, 384)) + "," +
                  i + (i ? "" : "," + PUCK_JS.length) + ");");
    }
    // One at a time, showing progress
    var k = 0;
    function next() {
      if (s.done) throw "Cancelled";
      if (k >= cmds.length) return;
      show(["Uploading", "code to Puck", Math.round(100 * k / cmds.length) + "%", "BTN: cancel"]);
      return send(s, "\x10" + cmds[k++] + "\n").then(next);
    }
    return next();
  }).then(function() {
    return ask(s, "E.CRC32(require('Storage').read('footrun.js'))+' '+E.CRC32(require('Storage').read('footrun.bin'))");
  }).then(function(reply) {
    if (reply != PUCK_JS_CRC + " " + PUCK_BIN_CRC) throw "the code didn't arrive intact - try again";
    s.lines = [];
    return send(s, "\x10eval(require('Storage').read('footrun.js'));\n");
  }).then(function() {
    return new Promise(function(resolve) { setTimeout(resolve, 2000); });
  }).then(function() {
    var err = s.lines.filter(function(l) { return /Error|ERROR|MEMORY/.test(l); })[0];
    if (err) throw "Puck: " + err;
  });
}

// Console text from the Puck, a line at a time
function onText(s, dv) {
  for (var i = 0; i < dv.byteLength; i++) {
    var c = dv.getUint8(i);
    if (c == 10 || c == 13) {
      var l = s.line.replace(/^[>\s]+/, "").trim();
      if (l) s.lines.push(l);
      if (s.lines.length > 20) s.lines.shift();
      s.line = "";
    } else if (c >= 32 && c < 127 && s.line.length < 100) s.line += String.fromCharCode(c);
  }
}

// Send text to the Puck's console, 20 bytes (one Bluetooth write) at a time
function send(s, text) {
  var i = 0;
  function next() {
    if (i >= text.length) return;
    var chunk = text.substr(i, 20);
    i += 20;
    return s.rx.writeValue(chunk).then(next);
  }
  return Promise.resolve().then(next);
}

// The result of a JS expression on the Puck, as a string
function ask(s, expr) {
  var tag = "FR" + Math.floor(Math.random() * 1e6);
  s.lines = [];
  return send(s, "\x10Bluetooth.println('" + tag + " '+(" + expr + "))\n").then(function() {
    return new Promise(function(resolve, reject) {
      var t0 = Date.now(), iv = setInterval(function() {
        for (var i = 0; i < s.lines.length; i++)
          if (s.lines[i].indexOf(tag + " ") == 0) { clearInterval(iv); return resolve(s.lines[i].substr(tag.length + 1)); }
        if (Date.now() - t0 > 5000 || s.done) { clearInterval(iv); reject("no reply from the Puck"); }
      }, 100);
    });
  });
}

function onDisconnect(s) {
  if (session != s || s.done || s.reconnecting) return;
  if (s.phase == "running") {
    stop("Puck disconnected - it keeps counting; tap to reconnect", true);
  } else stop("Puck disconnected");
}

// ---------------------------------------------------------------- Stopping

// End the session; with the Puck left running, or restarted (stopPuck)
function stop(reason, canReconnect, stopPuck) {
  var s = session;
  if (!s || s.done) return;
  s.done = true;
  if (s.timer) clearInterval(s.timer);
  function drop() { try { if (s.gatt && s.gatt.connected) s.gatt.disconnect(); } catch (e) {} }
  if (stopPuck && s.rx && s.gatt && s.gatt.connected)
    send(s, "\x03\x10Puck.accelOff();load();\n").then(drop, drop); // back to its saved program
  else drop();
  var lines = [reason, ""];
  if (run.strides) lines.push(run.strides + " strides", run.distance.toFixed(0) + " m", "");
  lines.push(canReconnect ? "Tap: reconnect" : "", "BTN: menu");
  show(lines);
  Bangle.setUI({ mode: "custom", btn: showMenu, touch: canReconnect ? connect : showMenu });
}

function showRunMenu() {
  var s = session;
  s.menu = true;
  E.showMenu({
    "": { title: "Foot Run", back: function() { s.menu = false; E.showMenu(); Bangle.setUI({ mode: "custom", btn: showRunMenu }); draw(); } },
    "Disconnect (Puck keeps counting)": function() { E.showMenu(); stop("Disconnected", true); },
    "Stop Puck": function() { E.showMenu(); stop("Puck stopped", false, true); },
    "Reset counts": function() {
      run.strides = 0; run.distance = 0; run.length = 0; run.cadence = 0;
      s.menu = false; E.showMenu(); Bangle.setUI({ mode: "custom", btn: showRunMenu }); draw();
    }
  });
}

function showMenu() {
  Bangle.setUI();
  E.showMenu({
    "": { title: "Foot Run", back: load },
    "Start": function() { E.showMenu(); connect(); },
    "Reset counts": function() { run.strides = 0; run.distance = 0; run.length = 0; run.cadence = 0; showMenu(); }
  });
}

// Don't leave the Puck connected if the app is closed
E.on("kill", function() {
  if (session && session.gatt && session.gatt.connected) try { session.gatt.disconnect(); } catch (e) {}
});

Bangle.loadWidgets();
Bangle.drawWidgets();
showMenu();
